\title{A Reflection Principle for Two-Summand Representation Counts,\\ with Applications to the Goldbach Framework}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We study the \emph{representation count} of a natural number $n$ as an unordered
sum of two elements drawn from a prescribed set $A \subseteq \NN$. Writing
$r_A(n)$ for the number of pairs $(p, n-p)$ with $p, n-p \in A$ and $p \le n-p$,
we prove a structural reflection theorem: when $A$ is symmetric about $n/2$ --
that is, closed under the involution $k \mapsto n-k$ on its elements not exceeding
$n$ -- the count $r_A(n)$ equals the number of elements of $A$ in the lower half
$\{0,1,\dots,\lfloor n/2\rfloor\}$. From this single principle we derive: (i) the
exact count $r_{\NN}(n) = \lfloor n/2\rfloor + 1$ for the unrestricted set; (ii) a
universal upper bound $r_A(n) \le \lfloor n/2\rfloor + 1$ valid for every set $A$;
and (iii) a complete parity-sensitive evaluation for the set of even numbers,
equal to $0$ when $n$ is odd and to $\lfloor (n/2)/2\rfloor + 1$ when $n$ is even.
We situate these results within the broader Goldbach circle of ideas, explain why
the primes evade the reflection principle, and discuss the sharp parity barrier at
$7$ governing the three-prime problem.
\end{abstract}

\maketitle

\section{Introduction}

Goldbach's binary conjecture asserts that every even integer $n \ge 4$ is the sum
of two primes. Despite its elementary statement and exhaustive numerical
confirmation, it remains open. A productive reframing replaces the binary
``is $n$ representable?'' with the quantitative ``in how many ways is $n$
representable?'', because the resulting \emph{representation function} carries
analytic, combinatorial, and probabilistic structure absent from a single truth
value.

Our central observation is that representation counting is, at heart, a problem
about a reflection. To split $n$ as $p + q$ is to choose the smaller part $p$; the
larger part $q = n - p$ is then forced. Counting unordered representations is
therefore counting admissible small parts in the lower half $[0, n/2]$, and a
representation $p$ is valid exactly when both $p$ and its mirror image $n - p$ lie
in $A$. When $A$ is invariant under this mirror, the upper-half condition becomes
automatic and the count collapses to a half-count.

\section{Definitions}

Throughout, $\NN = \{0,1,2,\dots\}$ and $\lfloor\,\cdot\,\rfloor$ denotes the floor.

\begin{definition}[Representation count]
For $A \subseteq \NN$ and $n \in \NN$, define
\[
r_A(n) = \#\bigl\{\, p \in \{0,\dots,n\} : p \in A,\ (n-p) \in A,\ p \le n-p \,\bigr\}.
\]
The condition $p \le n-p$ selects one representative from each unordered pair
$\{p, n-p\}$, so $r_A(n)$ counts unordered two-summand representations of $n$ with
both summands in $A$.
\end{definition}

\begin{definition}[Goldbach representation count]
The Goldbach partition count is $g(n) = r_{\PP}(n)$, where
$\PP = \{p \in \NN : p \text{ prime}\}$. Goldbach's binary conjecture is the
assertion $g(n) \ge 1$ for all even $n \ge 4$.
\end{definition}

\begin{definition}[Symmetry about $n/2$]
A set $A \subseteq \NN$ is \emph{symmetric about $n/2$} if
\[
\forall k,\quad k \in A \ \text{and}\ k \le n \ \Longrightarrow\ (n-k) \in A.
\]
Equivalently, the involution $k \mapsto n-k$ maps $A \cap [0,n]$ into $A$.
\end{definition}

Note that $p \le n-p$ is equivalent to $p \le \lfloor n/2\rfloor$ for integers; we
use these interchangeably.

\section{The Reflection Theorem}

\begin{theorem}[Reflection Theorem]\label{thm:reflection}
Let $A \subseteq \NN$ be symmetric about $n/2$. Then
\[
r_A(n) = \#\bigl\{\, p \in \{0,\dots,n\} : p \in A,\ p \le \lfloor n/2\rfloor \,\bigr\}.
\]
That is, $r_A(n)$ counts exactly the elements of $A$ in the lower half
$\{0,\dots,\lfloor n/2\rfloor\}$.
\end{theorem}

\begin{proof}
It suffices to show that the defining predicate of $r_A(n)$,
\[
P(p):\quad p \in A \ \wedge\ (n-p)\in A \ \wedge\ p \le n - p,
\]
agrees over $p \in \{0,\dots,n\}$ with $Q(p): p \in A \ \wedge\ p \le \lfloor n/2\rfloor$.

\emph{($P \Rightarrow Q$.)} If $P(p)$ holds, then $p \in A$ and $p \le n-p$, the
latter giving $p \le \lfloor n/2\rfloor$.

\emph{($Q \Rightarrow P$.)} If $Q(p)$ holds, then $p \in A$ and
$p \le \lfloor n/2\rfloor \le n$. With $p \le n$, $p \in A$, and symmetry,
$(n-p) \in A$; and $p \le \lfloor n/2\rfloor$ gives $p \le n-p$.

Since the predicates coincide on $\{0,\dots,n\}$, the filtered sets are equal, and
so are their cardinalities.
\end{proof}

\section{The unrestricted count and a universal bound}

\begin{lemma}[Lower-half cardinality]\label{lem:lower}
For $m \le n$, $\#\{ p \in \{0,\dots,n\} : p \le m \} = m + 1.$
\end{lemma}
\begin{proof}
The set is exactly $\{0,1,\dots,m\}$, which has $m+1$ elements.
\end{proof}

\begin{lemma}[Even count in an initial segment]\label{lem:even}
For $M \in \NN$, $\#\{ p \in \{0,\dots,M\} : p \text{ even} \} = \lfloor M/2\rfloor + 1.$
\end{lemma}
\begin{proof}
The map $i \mapsto 2i$ is a bijection from $\{0,\dots,\lfloor M/2\rfloor\}$ onto
$\{p \le M : p \text{ even}\}$, with inverse $p \mapsto p/2$. A bijection
preserves cardinality, and the domain has $\lfloor M/2\rfloor + 1$ elements.
\end{proof}

\begin{theorem}[Unrestricted count]\label{thm:full}
For the full set $A = \NN$, \ $r_{\NN}(n) = \lfloor n/2\rfloor + 1.$
\end{theorem}
\begin{proof}
$\NN$ is symmetric about $n/2$, so Theorem~\ref{thm:reflection} reduces
$r_{\NN}(n)$ to the count of all $p \le \lfloor n/2\rfloor$, which is
$\lfloor n/2\rfloor + 1$ by Lemma~\ref{lem:lower} (with $m = \lfloor n/2\rfloor \le n$).
\end{proof}

\begin{theorem}[Universal upper bound]\label{thm:bound}
For every $A \subseteq \NN$ and every $n$, \ $r_A(n) \le \lfloor n/2\rfloor + 1.$
\end{theorem}
\begin{proof}
Every counted $p$ satisfies $p \le n-p$, hence $p \le \lfloor n/2\rfloor$. The set
counted by $r_A(n)$ thus injects into $\{p \le \lfloor n/2\rfloor\}$, of
cardinality $\lfloor n/2\rfloor + 1$ by Lemma~\ref{lem:lower}.
\end{proof}

\section{The even summand set: a parity dichotomy}

Let $E = \{m \in \NN : m \text{ even}\}$.

\begin{theorem}[Odd targets]\label{thm:odd}
If $n$ is odd, then $r_E(n) = 0$.
\end{theorem}
\begin{proof}
A counted $p$ would require $p$ and $n-p$ both even; but then $n = p + (n-p)$ is
even, contradicting $n$ odd.
\end{proof}

\begin{theorem}[Even targets]\label{thm:even}
If $n$ is even, then $r_E(n) = \lfloor (n/2)/2\rfloor + 1.$
\end{theorem}
\begin{proof}
For even $n$, $E$ is symmetric about $n/2$: if $k$ is even and $k \le n$, then
$n-k$ is even. Theorem~\ref{thm:reflection} reduces $r_E(n)$ to the count of even
$p \le n/2$, which is $\lfloor (n/2)/2\rfloor + 1$ by Lemma~\ref{lem:even} with
$M = n/2$.
\end{proof}

\section{Why the primes resist}

The reflection principle computes $r_A(n)$ whenever $A$ is symmetric about $n/2$.
The primes are conspicuously not symmetric: for prime $p$, $n-p$ is prime only
sometimes -- and that this happens at least once is exactly Goldbach's conjecture.
The reflection theorem instead furnishes an exact ceiling
$g(n) \le \lfloor n/2\rfloor + 1$ and solved shadow problems (the unrestricted and
even counts) that any complete theory of $g(n)$ must reproduce. The
Hardy--Littlewood circle method attacks the remaining gap by writing the ordered
count as a Fourier integral of the prime exponential sum
$S(\alpha) = \sum_{p \le n} e^{2\pi i \alpha p}$,
\[
R(n) = \int_0^1 S(\alpha)^2 e^{-2\pi i \alpha n}\, d\alpha,
\]
with conjectured asymptotic
$R(n) \sim \mathfrak{S}(n)\, n / (\log n)^2$, where $\mathfrak{S}(n)$ is the
singular series.

\section{The ternary problem and the sharp threshold at 7}

\begin{proposition}[Reduction and sharp threshold]\label{prop:ternary}
If $n$ is odd and $n \ge 7$, then $n-3$ is even and $n-3 \ge 4$; hence any binary
Goldbach split $n-3 = p+q$ yields a ternary representation $n = 3 + p + q$. The
threshold $7$ is sharp: it is the least odd number for which $n-3$ lands in the
even-Goldbach domain $\{4,6,8,\dots\}$.
\end{proposition}
\begin{proof}
For odd $n \ge 7$, $n-3$ is even and $\ge 4$. For odd $n \in \{1,3,5\}$,
$n-3 \in \{-2,0,2\}$ never lies in $\{4,6,\dots\}$, so the reduction is
unavailable.
\end{proof}

\section{Discussion and future work}

The reflection principle separates the easy, symmetric structure of two-summand
counts from the hard, asymmetric prime arithmetic of Goldbach's conjecture. By
isolating $r_A(n)$ as a finite, exactly computable object, the framework converts
representability into a growth question about a count. Future directions include:
a bounded-summand strengthening (every even $n \ge 6$ admits $n = p+q$ with smaller
prime $p \le C(\log n)^2$); residue-balanced partitions generalizing the rigid
$\bmod 4$ dichotomy to a local-density law tied to the singular series;
monotonicity and divergence of the count $r(n) \to \infty$; and the sharpness of
the ternary threshold at $7$.

\section{Conclusion}

We established a reflection principle for two-summand representation counts and
used it to compute the unrestricted count, a universal upper bound, and a complete
parity-sensitive evaluation for even summands -- a rigorous, self-contained
combinatorial foundation for the quantitative study of Goldbach's conjecture.

\end{document}

